
/* ================= RENDER FRAMEWORK ================= */
const chip=(t,c)=>`<span class="chip ${c||''}">${esc(t)}</span>`;
const stc=s=>`<span class="st chip ${STC[s]||''}" title="${esc(STL[s]||s)}">${esc(s)}</span>`;
const toast=m=>{const t=$('#toast');t.textContent=m;t.classList.add('on');clearTimeout(toast.h);toast.h=setTimeout(()=>t.classList.remove('on'),2600)};
const ACT={};const VIEWS={};const CH={};
function openModal(html,mount){$('#mbody').innerHTML=html;$('#modal').hidden=false;if(mount)mount();$('#modal').scrollTop=0}
function closeModal(){$('#modal').hidden=true;$('#mbody').innerHTML=''}
ACT.closeModal=closeModal;
const tabs=(key,list)=>{const cur=S.ui.tab[key]||list[0][0];return[`<div class="tabs" role="tablist">${list.map(([k,l])=>`<button role="tab" class="${k===cur?'on':''}" data-act="tab" data-k="${key}" data-v="${k}">${esc(l)}</button>`).join('')}</div>`,cur]};
ACT.tab=el=>{S.ui.tab[el.dataset.k]=el.dataset.v;render()};
ACT.go=el=>{S.ui.view=el.dataset.v;if(el.dataset.t)S.ui.tab[el.dataset.v]=el.dataset.t;render();window.scrollTo(0,0)};

const fval=(root,name)=>{const el=root.querySelector(`[name="${name}"]`);return el?(el.type==='checkbox'?el.checked:el.value.trim()):''};
const isOwner=()=>S.ui.role==='owner';

function counts(){
  const mk=curMK;let ot=0,mp=0;const sc=SE().filter(e=>e.status!=='exited');
  sc.forEach(e=>{[mkShift(mk,-1),mk].forEach(m=>{if(S.payroll[m])return;const s=msum(e,m);ot+=s.pend.length;mp+=s.mps.length})});
  const ins=id=>{const e=E(id);return!!e&&inScope(e)};
  return{ot:can('attendance')?ot:0,mp:can('attendance')?mp:0,lv:can('leave')?S.leaves.filter(l=>l.status==='pending'&&ins(l.empId)).length:0,
    docs:can('docs')?S.docs.filter(d=>ins(d.empId)&&!['completed','void','hold'].includes(d.status)&&nextSigner(d)==='employer').length:0,
    seps:can('exits')?S.seps.filter(s=>ins(s.empId)&&!['closed','withdrawn'].includes(s.status)).length:0,
    tk:can('helpdesk')?S.tickets.filter(t=>ins(t.empId)&&t.status!=='resolved').length:0,
    onb:sc.filter(e=>e.status==='onboarding').length,
    cr:can('staff')?S.changeReqs.filter(r=>r.status==='pending'&&ins(r.empId)).length:0,
    ret:can('exits')?S.employees.filter(e=>inScope(e)&&(e.assets||[]).some(a=>a.status==='declared')).length:0}
}
const docsFor=me=>S.docs.filter(d=>d.empId===me.id&&!['completed','void','hold'].includes(d.status)&&nextSigner(d)==='employee').length;
function render(){
  runRetention();
  if(window.EMP_MODE)return renderEmp();
  if(!S.ui.user||(S.ui.user!=='owner'&&!user()))return renderAdminLogin();
  if(S.ui.role!=='owner'&&!E(S.ui.role))S.ui.role='owner';
  const own=isOwner();const c=own?counts():null;const me=own?null:E(S.ui.role);
  const NAV=own?[['dashboard','Dashboard',c.ot+c.mp+c.lv+c.docs+c.seps+c.tk+c.cr+c.ret,1],['mysvc','Salon HR plan & partner',0,isBoss()],['employees','Employees',c.onb+c.cr,1],['attendance','Attendance & OT',c.ot+c.mp,can('attendance')],['roster','Weekly roster',0,can('roster')],['leave','Leave',c.lv,can('leave')],['payroll','Payroll',0,isBoss()],['performance','Productivity',0,can('targets')],['documents','Documents & e-sign',c.docs,1],['separations','Exits',c.seps,can('exits')],['helpdesk','Helpdesk',c.tk,can('helpdesk')],['policies','Policies',0,1],['team','Branches & managers',0,isBoss()],['customise','Customise',0,isBoss()],['services','PF/ESI & BGV',0,isBoss()],['settings','Settings',0,isBoss()]].filter(n=>n[3])
    :[['home','Punch clock',0],['onboarding','Joining form',me.onb&&me.onb.status==='pending'?1:0],['myatt','My attendance',0],['myleave','My leave',0],['payslips','Payslips',0],['myperf','My targets',0],['mydocs','Documents',docsFor(me)],['profile','My profile',0],['vwh','Work history',0],['resign','Resign / exit',0],['myhelp','Helpdesk',0],['mypolicies','Policies',0]];
  if(!NAV.some(n=>n[0]===S.ui.view))S.ui.view=NAV[0][0];
  const u=user(),brs=myBranches();
  const top=own?`<div class="who">${brs.length>1?`<select data-change="branch" aria-label="Branch" style="width:auto"><option value="all">All branches</option>${brs.map(b=>`<option value="${b.id}"${S.ui.branch===b.id?' selected':''}>${esc(b.name)}</option>`).join('')}</select>`:`<span class="chip c-b">${esc((brs[0]||{}).name||'')}</span>`}<select data-change="preview" aria-label="Preview staff app" style="width:auto"><option value="">Preview staff app as…</option>${SE().filter(e=>e.status!=='exited').map(e=>`<option value="${e.id}">${esc(e.name)}</option>`).join('')}</select><span class="small muted">${u?esc(u.name)+' · '+esc(u.title):esc(S.settings.owner)+' · Owner'}</span><a class="btn s" href="#home">Website</a><button class="btn s" data-act="adminLogout">Log out</button></div>`
    :`<div class="who"><span class="chip c-warn">Previewing the staff app as ${esc(me.name)}</span><button class="btn s p" data-act="backAdmin">Back to admin</button></div>`;
  $('#app').innerHTML=`<div class="wrap"><aside class="rail"><div class="brand"><i></i><div>Salon HR<small>${esc(S.settings.salon)}</small></div></div>
    <nav class="nav">${NAV.map(n=>`<button class="${S.ui.view===n[0]?'on':''}" data-act="go" data-v="${n[0]}">${esc(n[1])}${n[2]?`<span class="badge">${n[2]}</span>`:''}</button>`).join('')}</nav>
    <div class="navsec">Prototype · data stays in this browser</div></aside>
    <main>${S.ui.support&&own?`<div class="note" style="margin-bottom:12px;display:flex;flex-wrap:wrap;gap:10px;align-items:center"><b>Salon HR support (${esc(S.ui.support)}) is viewing this account.</b><span class="sp small">The salon owner can see this session in the audit log.</span><button class="btn s" data-act="endSupport">End support session</button></div>`:''}<div class="top"><div></div>${top}</div>${VIEWS[S.ui.view]()}</main></div>`;
  drawMom();save();
}
function renderAdminLogin(){const st=S.ui.alogin||{};
  const ppl=[{id:'owner',name:S.settings.owner,title:'Owner · all branches',phone:S.settings.phone}].concat(S.users.map(u=>({id:u.id,name:u.name,title:u.title+' · '+u.branchIds.map(b=>BR(b).name).join(', '),phone:u.phone})));
  $('#app').innerHTML=`<div class="elogin"><div class="brand" style="color:var(--ink);justify-content:center;font-size:26px"><i></i><div>Salon HR<small style="color:var(--mute);opacity:1">Admin · ${esc(S.settings.salon)}</small></div></div>
  <div class="card" style="margin-top:22px">${!st.id?`<h2>Owner / manager login</h2><p class="sub">Use your registered mobile number.</p><form id="falog" style="margin-top:14px"><label class="f">Mobile number<input name="ph" inputmode="tel" autocomplete="tel"></label><button class="btn p" style="width:100%;margin-top:12px">Send OTP</button></form>`
  :`<h2>Enter OTP</h2><p class="sub">Sent to ${esc(st.phone)}. Demo OTP: 123456</p><form id="faotp" style="margin-top:14px"><label class="f">6-digit OTP<input name="otp" inputmode="numeric" maxlength="6" autocomplete="one-time-code"></label><button class="btn p" style="width:100%;margin-top:12px">Verify & log in</button></form><button class="btn" style="width:100%;margin-top:8px" data-act="aloginBack">Change number</button>`}</div>
  ${!st.id?`<div class="card"><h3>Demo logins — tap to fill</h3><div class="list" style="margin-top:6px">${ppl.map(x=>`<div class="click" data-act="aDemo" data-id="${x.id}" style="cursor:pointer"><span class="sp"><b>${esc(x.name)}</b><br><span class="small muted">${esc(x.title)}</span></span><span class="small">${esc(x.phone)}</span></div>`).join('')}</div></div>`:''}<p style="text-align:center"><a href="#login">← Back to Salon HR login</a></p></div>`;save()}
const phOf=id=>id==='owner'?S.settings.phone:(S.users.find(u=>u.id===id)||{}).phone;
ACT.aDemo=el=>{S.ui.alogin={id:el.dataset.id,phone:phOf(el.dataset.id)};render()};
ACT.aloginBack=()=>{S.ui.alogin={};render()};
ACT.adminLogout=()=>{S.ui.user=null;S.ui.alogin={};S.ui.view='dashboard';S.ui.branch='all';render()};
ACT.backAdmin=()=>{S.ui.role='owner';S.ui.view='dashboard';render()};
document.addEventListener('submit',ev=>{const f=ev.target;
  if(f.id==='falog'){ev.preventDefault();const n=String(fval(f,'ph')).replace(/\D/g,'').slice(-10);const id=['owner',...S.users.map(u=>u.id)].find(i=>String(phOf(i)).replace(/\D/g,'').slice(-10)===n);if(!id)return toast('Number not registered as owner or manager');S.ui.alogin={id,phone:phOf(id)};render()}
  if(f.id==='faotp'){ev.preventDefault();if(fval(f,'otp')!=='123456')return toast('Wrong OTP (demo: 123456)');S.ui.user=S.ui.alogin.id;S.ui.alogin={};S.ui.role='owner';S.ui.branch='all';S.ui.view='dashboard';render();toast('Logged in')}});
CH.branch=el=>{S.ui.branch=el.value;render()};
CH.preview=el=>{if(!el.value)return;S.ui.role=el.value;S.ui.view='home';render()};
const head=(t,sub,right)=>`<div class="row" style="margin-bottom:16px"><div class="sp"><h1>${esc(t)}</h1>${sub?`<div class="sub">${sub}</div>`:''}</div>${right||''}</div>`;

/* ================= OWNER: DASHBOARD ================= */
VIEWS.dashboard=()=>{
  const c=counts(),act=SE().filter(e=>['active','onboarding','notice'].includes(e.status));
  const today=act.map(e=>({e,o:day(e,todayS)}));
  const present=today.filter(x=>x.r||x.o.r.in).length,onLeave=today.filter(x=>x.o.leave).length;
  const head_=act.length;
  const alerts=[];
  const soon=SE().filter(e=>e.status==='exited'&&!e.archived&&daysLeft(purgeOn(e))<=14);if(soon.length)alerts.push(['warn',`Personal details of ${soon.map(e=>e.name).join(', ')} will be deleted within 14 days (${S.settings.keepMonths}-month retention after exit). Save anything you need from Past employees.`]);
  if(!isBoss())alerts.length=0;
  if(head_>=20&&!S.settings.pf)alerts.push(['bad','PF is mandatory at 20+ employees. Turn on the PF service.']);
  if(head_>=10&&!S.settings.esi)alerts.push(['bad','ESI is mandatory at 10+ employees. Turn on the ESI service.']);
  if(head_>=10)alerts.push(['warn','10+ employees: constitute a POSH Internal Committee and record it in Settings.']);
  if(!S.settings.minWage)alerts.push(['info','Enter your zone\'s minimum wage in Settings to enable minimum-wage checks on every payslip.']);
  const unsigned=SE().filter(e=>e.status!=='exited'&&!S.docs.some(d=>d.empId===e.id&&d.type==='appointment'&&d.status==='completed'));
  if(unsigned.length)alerts.push(['warn',`Appointment letter not fully signed: ${unsigned.map(e=>e.name).join(', ')}. Appointment letters are mandatory under the Labour Codes.`]);
  S.seps.filter(s=>inScope(E(s.empId))&&s.fnf&&!s.fnf.paid&&s.status!=='closed').forEach(s=>alerts.push(['warn',`F&F for ${E(s.empId).name} due by ${fdate(s.fnf.due)} (2 working days rule).`]));
  const prev=mkShift(curMK,-1);
  const todo=[['attendance','ot','Overtime awaiting your approval',c.ot],['attendance','mp','Missed punches to regularise',c.mp],['leave','','Leave requests',c.lv],['documents','','Documents waiting for your signature',c.docs],['separations','','Resignations / exits in progress',c.seps],['helpdesk','','Open helpdesk tickets',c.tk],['employees','','New joiners in onboarding',c.onb],['employees','','Profile change requests',c.cr],['separations','','Returned items to approve (exits)',c.ret]].filter(x=>x[3]);
  return head(`Good ${NOW.getHours()<12?'morning':NOW.getHours()<17?'afternoon':'evening'}, ${(user()?user().name:S.settings.owner).split(' ')[0]}`,fdate(todayS)+' · '+esc(S.settings.salon))+
  `<div class="grid g4" style="margin-bottom:16px"><div class="kpi"><b>${head_}</b><span>Staff on roll</span></div><div class="kpi"><b>${today.filter(x=>x.o.r.in).length}</b><span>Punched in today</span></div><div class="kpi"><b>${onLeave}</b><span>On leave today</span></div><div class="kpi"><b>${S.payroll[prev]?'Released':'Pending'}</b><span>${mname(prev)} payroll</span></div></div>
  <div class="grid g2"><div class="card"><h2>Needs your action</h2>${todo.length?`<div class="list">${todo.map(t=>`<div><span class="dot" style="background:var(--berry)"></span><span class="sp">${t[2]}</span><b>${t[3]}</b><button class="btn s" data-act="go" data-v="${t[0]}" data-t="${t[1]}">Open</button></div>`).join('')}</div>`:'<div class="empty">All clear. Nothing is waiting for you.</div>'}</div>
  <div class="card"><h2>On the floor today</h2><div class="list">${today.map(({e,o})=>{const r=o.r;const s=r.out?'Left '+r.out:r.mealOut&&!r.mealIn?'On meal break':r.in?'In since '+r.in:o.leave?'On leave':o.status==='WO'?'Weekly off':'Not in yet';
    return`<div><span class="dot" style="background:${r.in&&!r.out?'var(--ok)':o.leave||o.status==='WO'?'var(--info)':'var(--mute)'}"></span><span class="sp"><b>${esc(e.name)}</b><br><span class="small muted">${esc(bn(e))} · ${esc(o.sh.name)} ${o.sh.start}–${o.sh.end}</span></span><span class="small">${s}${o.late?' · '+chip('Late '+o.late+'m','c-warn'):''}</span></div>`}).join('')}</div></div></div>
  <div class="card"><h2>Compliance watch</h2>${alerts.length?`<div class="list">${alerts.map(a=>`<div>${chip(a[0]==='bad'?'Action':a[0]==='warn'?'Check':'Tip','c-'+a[0])}<span class="sp small">${esc(a[1])}</span></div>`).join('')}</div>`:'<div class="empty">No compliance gaps found.</div>'}</div>
  <div class="card"><h2>Recent activity</h2><div class="list">${S.audit.slice(0,8).map(a=>`<div><span class="small muted" style="width:150px">${fdt(a.at)}</span><span class="sp small">${esc(a.text)}</span><span class="small muted">${esc(a.by)}</span></div>`).join('')||'<div class="empty">Actions taken in the HRMS appear here.</div>'}</div></div>`;
};

/* ================= OWNER: EMPLOYEES ================= */
const ESTC={active:'c-ok',onboarding:'c-warn',notice:'c-info',exited:''};
CH.desSel=el=>{const w=el.closest('form').querySelector('#newDesW');if(w){w.hidden=el.value!=='__new';if(!w.hidden)w.querySelector('input').focus()}};
CH.empSt=el=>{S.ui.tab.empSt=el.value;render()};CH.empQ=el=>{S.ui.tab.empQ=el.value;render()};
function crCard(){if(!can('staff'))return'';const L=S.changeReqs.filter(r=>r.status==='pending'&&inScope(E(r.empId)));if(!L.length)return'';
  return`<div class="card"><h2>Profile change requests (${L.length})</h2><p class="sub">Employees asked to change details that affect pay or compliance.</p><table class="stack"><thead><tr><th>Employee</th><th>Change</th><th>Requested</th><th></th></tr></thead><tbody>${L.map(r=>`<tr><td><b>${esc(E(r.empId).name)}</b></td><td class="small">${Object.entries(r.fields).map(([k,v])=>`${esc(v.label)}: <s class="muted">${esc(v.old||'—')}</s> → <b>${esc(v.qr?'New QR image':v.new)}</b>`).join('<br>')}${Object.values(r.fields).some(v=>v.qr)?`<br><img src="${r.fields.qr.new}" alt="New UPI QR" style="height:70px;border-radius:6px;margin-top:4px">`:''}</td><td class="small">${fdt(r.at)}</td><td><span class="row" style="gap:6px;flex-wrap:nowrap"><button class="btn s ok" data-act="crDo" data-id="${r.id}" data-v="approved">Approve</button><button class="btn s bad" data-act="crDo" data-id="${r.id}" data-v="rejected">Reject</button></span></td></tr>`).join('')}</tbody></table></div>`}
ACT.crDo=el=>{const r=S.changeReqs.find(x=>x.id===el.dataset.id),e=E(r.empId);r.status=el.dataset.v;r.by=actorName();r.decidedAt=new Date().toISOString();
  if(r.status==='approved')Object.entries(r.fields).forEach(([k,v])=>setEmpField(e,k,v.new));audit(`Profile change ${r.status} for ${e.name}`);render()};
function setEmpField(e,k,v){const d=(e.onb.data=e.onb.data||{});if(k==='phone')e.phone=v;else if(k==='email')e.email=v;else if(k==='upi')(e.pay=e.pay||{}).upi=v;else if(k==='qr')(e.pay=e.pay||{}).qr=v;else d[k]=v}
const shiftOpts=v=>S.shifts.map(s=>`<option value="${s.id}"${s.id===v?' selected':''}>${esc(s.name)} ${s.start}–${s.end}</option>`).join('');
const dowOpts=v=>DOW.map((d,i)=>`<option value="${i}"${i===+v?' selected':''}>${d}</option>`).join('');
const dl=(id,arr)=>`<datalist id="${id}">${arr.map(x=>`<option value="${esc(x)}">`).join('')}</datalist>`;
function empForm(e,ro){e=e||{};const dis=ro?' disabled':'';return`<fieldset style="border:0;padding:0;margin:0"${dis}><div class="fg">
  <label class="f">Full name *<input name="name" required value="${esc(e.name)}"></label>
  <label class="f">Mobile * (used for login)<input name="phone" value="${esc(e.phone)}" inputmode="tel"></label>
  <label class="f">Email<input name="email" value="${esc(e.email)}"></label>
  <label class="f">Gender<select name="gender">${['F','M','O'].map(g=>`<option${e.gender===g?' selected':''} value="${g}">${g==='F'?'Female':g==='M'?'Male':'Other'}</option>`).join('')}</select></label>
  <label class="f">Designation *<select name="designation" data-change="desSel"><option value="">Select designation</option>${[...new Set([...S.settings.designations,...(e.designation?[e.designation]:[])])].map(d=>`<option${d===e.designation?' selected':''}>${esc(d)}</option>`).join('')}${can('staff')?'<option value="__new">+ Add new designation…</option>':''}</select></label>
  <label class="f" id="newDesW" hidden>New designation name *<input name="newDes" placeholder="e.g. Sr. Nail Artist"></label>
  <label class="f">Department<select name="dept">${S.settings.depts.map(d=>`<option${e.dept===d?' selected':''}>${esc(d)}</option>`).join('')}</select></label>
  <label class="f">Branch *<select name="branchId">${myBranches().map(b=>`<option value="${b.id}"${b.id===e.branchId?' selected':''}>${esc(b.name)}</option>`).join('')}</select></label>
  <label class="f">Date of joining *<input type="date" name="doj" value="${esc(e.doj||todayS)}"></label>
  <label class="f">Employment type<select name="type">${['Probation','Permanent','Fixed-term'].map(d=>`<option${e.type===d?' selected':''}>${d}</option>`).join('')}</select></label>
  <label class="f">Default shift<select name="shiftId">${shiftOpts(e.shiftId)}</select></label>
  <label class="f">Fixed weekly off<select name="weeklyOff">${dowOpts(e.weeklyOff??2)}</select></label>
  <label class="f">Gross fixed pay / month (₹) *<input type="number" name="gross" min="0" value="${esc(e.gross||18000)}"></label>
  <label class="f">Monthly service target (₹)<input type="number" name="target" min="0" value="${esc(e.target??80000)}"></label>
  <label class="f">Service incentive %<input type="number" step="0.5" name="comm" value="${esc(e.comm??6)}"></label>
  <label class="f">Product incentive %<input type="number" step="0.5" name="prodComm" value="${esc(e.prodComm??10)}"></label>
  <label class="chk"><input type="checkbox" name="pf" ${e.pf!==false?'checked':''}> Enrol in PF</label>
  <label class="chk"><input type="checkbox" name="esi" ${e.esi!==false?'checked':''}> Enrol in ESI (if gross ≤ ₹${S.settings.esiCeil.toLocaleString('en-IN')})</label></div></fieldset>`}
function readEmp(root,e){['name','phone','email','gender','designation','dept','branchId','doj','type','shiftId'].forEach(k=>e[k]=fval(root,k));
  if(e.designation==='__new'){const n=fval(root,'newDes');e.designation=n;if(n&&!S.settings.designations.includes(n)){S.settings.designations.push(n);audit('Added designation '+n)}}
  ['weeklyOff','gross','target','comm','prodComm'].forEach(k=>e[k]=+fval(root,k)||0);e.pf=fval(root,'pf');e.esi=fval(root,'esi')&&e.gross<=S.settings.esiCeil;return e}
const phoneTaken=(ph,id)=>{const n=String(ph).replace(/\D/g,'').slice(-10);return S.employees.some(x=>x.id!==id&&x.status!=='exited'&&String(x.phone).replace(/\D/g,'').slice(-10)===n)};
ACT.addEmp=()=>openModal(`<h2>Add employee</h2><p class="sub">The employee gets an SMS invite to the staff app to fill their part of the joining form, upload documents and sign the appointment letter.</p><form id="fe">${empForm()}<div class="row" style="margin-top:16px"><span class="sp"></span><button class="btn p">Create & send invite</button></div></form>`,()=>{
  $('#fe').onsubmit=ev=>{ev.preventDefault();const e=readEmp($('#fe'),{id:uid('e'),status:'onboarding',lb:Object.fromEntries(LT().map(t=>[t.code,t.days])),onb:{status:'pending',data:{},docs:[]},refs:[],uan:'',esic:'',lwd:null,custom:{},pay:{upi:'',qr:null},assets:[]});
    if(!e.name||!e.phone||!e.designation)return toast('Name, mobile and designation are required');if(phoneTaken(e.phone))return toast('This mobile is already registered to another employee');
    e.code='AUR'+String(S.employees.length+1).padStart(3,'0');S.employees.push(e);S.perf[e.id]={};
    makeDoc('appointment',e,{});audit('Added employee '+e.name+' and sent staff-app invite');closeModal();render();toast('Invite sent to '+e.name+'. Appointment letter drafted.')}});
ACT.emp=el=>empModal(el.dataset.id);
const fieldInput=(f,v,pre)=>{const n=(pre||'')+f.id;const req=f.req?' *':'';
  if(f.type==='select')return`<label class="f">${esc(f.label)}${req}<select name="${n}"><option value="">Select</option>${String(f.options||'').split(',').map(o=>o.trim()).filter(Boolean).map(o=>`<option${o===v?' selected':''}>${esc(o)}</option>`).join('')}</select></label>`;
  if(f.type==='yesno')return`<label class="f">${esc(f.label)}${req}<select name="${n}"><option value="">Select</option>${['Yes','No'].map(o=>`<option${o===v?' selected':''}>${o}</option>`).join('')}</select></label>`;
  if(f.type==='textarea')return`<label class="f" style="grid-column:1/-1">${esc(f.label)}${req}<textarea name="${n}">${esc(v)}</textarea></label>`;
  return`<label class="f">${esc(f.label)}${req}<input name="${n}" type="${f.type==='date'?'date':f.type==='number'?'number':'text'}" value="${esc(v)}"></label>`};
function empModal(id,tab){const e=E(id);S.ui.tab.emp=tab||S.ui.tab.emp||'ov';const ro=!can('staff');
  const [tb,cur]=tabs('emp',[['ov','Profile & pay'],['onb','Joining form'],['pay','Bank & UPI'],['lv','Leave quota'],['ast','Salon property'],['ver','Verification & BGV'],['docs','Documents'],['act','Actions']]);
  let body='';const F=S.settings.form;
  if(cur==='ov')body=`<form id="fe">${empForm(e,ro)}${ro?'<p class="small muted">You can view but not edit staff details. The owner can give you this permission.</p>':`<div class="row" style="margin-top:14px"><span class="small muted sp">Salary structure: Basic ${inr(structure(e.gross).basic)} · HRA ${inr(structure(e.gross).hra)} · Special ${inr(structure(e.gross).spl)} (Basic kept at 50%)</span><button class="btn p">Save changes</button></div>`}</form>`;
  if(cur==='onb'){const o=e.onb||{},d=o.data||{},cu=e.custom||{};const empF=F.filter(f=>f.who==='employee'&&!['file','refs','qr'].includes(f.type));const erF=F.filter(f=>f.who==='employer');
    const missing=erF.filter(f=>f.req&&!cu[f.id]).length;
    body=`<div class="row" style="margin-bottom:8px"><h3 class="sp">Employer section</h3>${missing?chip(missing+' required pending','c-bad'):chip('Complete','c-ok')}</div><form id="fer" class="fg">${erF.map(f=>fieldInput(f,cu[f.id],'er_')).join('')||'<p class="muted small">No employer questions. Add them in Customise → Joining form.</p>'}${ro?'':'<div style="align-self:end"><button class="btn p">Save employer section</button></div>'}</form>
    <div class="row" style="margin:18px 0 8px"><h3 class="sp">Employee section</h3>${chip(o.status==='pending'?'Not submitted':o.status==='verified'?'Verified':'Submitted '+fdt(o.submittedAt),o.status==='verified'?'c-ok':o.status==='pending'?'c-warn':'c-info')}</div>
    <form id="fee" class="fg">${empF.map(f=>fieldInput(f,f.core?(f.key==='aadhaar'?mask(d[f.key]):f.key==='upi'?(e.pay||{}).upi:d[f.key]):cu[f.id],'ee_')).join('')}${ro?'':`<div style="align-self:end"><button class="btn">Save corrections</button></div>`}</form>
    <p class="small muted" style="margin-top:6px">Documents uploaded: ${esc((o.docs||[]).join(', ')||'none yet')}. Corrections you make are logged and shown to the employee.</p>
    ${(o.docs||[]).map(n=>FILES[e.id+n]?`<div class="small">Preview: ${esc(n)} <img src="${FILES[e.id+n]}" alt="${esc(n)}" style="max-height:80px;border-radius:6px;vertical-align:middle"></div>`:'').join('')}`}
  if(cur==='pay'){const d=(e.onb&&e.onb.data)||{},p=e.pay||{};body=`<form id="fpay" class="fg"><label class="f">Bank name<input name="bank" value="${esc(d.bank)}"></label><label class="f">Account number<input name="acct" value="${esc(d.acct)}" inputmode="numeric"></label><label class="f">IFSC<input name="ifsc" value="${esc(d.ifsc)}" style="text-transform:uppercase"></label><label class="f">UPI ID<input name="upi" value="${esc(p.upi)}" placeholder="name@bank"></label><label class="f">UPI QR code (image)<input type="file" name="qrf" accept="image/*"></label>${ro?'':'<div style="align-self:end"><button class="btn p">Save payment details</button></div>'}</form>
    <div class="row" style="margin-top:14px;align-items:flex-start">${p.qr?`<img src="${p.qr}" alt="UPI QR" style="width:150px;border-radius:10px;border:1px solid var(--line)">`:'<div class="empty" style="flex:1">No UPI QR uploaded yet.</div>'}<div class="sp small muted">Salary can be paid by bank transfer (NEFT/IMPS) or UPI. Payroll shows these details on each employee's "Pay" button. Employees can request changes from their app; changes need your approval.</div></div>`}
  if(cur==='lv')body=`<p class="sub" style="margin-bottom:10px">Set this employee's balance for each leave type. Types and yearly quotas are set in Customise → Leave types.</p><div class="fg">${LT().map(t=>`<label class="f">${esc(t.name)} (${t.code})${t.paid?'':' · unpaid'}<input type="number" step="0.5" min="0" value="${e.lb[t.code]??0}" data-change="lbSet" data-id="${e.id}" data-k="${t.code}" ${can('leave')?'':'disabled'}></label>`).join('')}</div>`;
  if(cur==='ast')body=`<p class="sub" style="margin-bottom:10px">Everything issued to the employee. At exit each item must be returned and approved by a manager or the owner before F&F can be processed.</p><table class="stack"><thead><tr><th>Item</th><th class="n">Qty</th><th class="n">Value</th><th>Issued</th><th>Status</th><th></th></tr></thead><tbody>${(e.assets||[]).map(a=>`<tr><td>${esc(a.name)}</td><td class="n">${a.qty}</td><td class="n">${inr(a.value)}</td><td class="small">${fdate(a.issuedOn)}</td><td>${astChip(a)}</td><td>${can('exits')||can('staff')?`<span class="row" style="gap:4px;flex-wrap:nowrap">${a.status!=='approved'&&a.status!=='issued'||a.status==='declared'?'':''}${['issued','declared'].includes(a.status)&&e.status!=='active'&&e.status!=='onboarding'?`<button class="btn s ok" data-act="astSet" data-id="${e.id}" data-a="${a.id}" data-v="approved">Approve return</button><button class="btn s bad" data-act="astSet" data-id="${e.id}" data-a="${a.id}" data-v="lost">Not returned</button>`:''}${a.status==='issued'&&['active','onboarding'].includes(e.status)?`<button class="btn s" data-act="astDel" data-id="${e.id}" data-a="${a.id}">Remove</button>`:''}</span>`:''}</td></tr>`).join('')||'<tr><td colspan="6" class="muted">Nothing issued yet.</td></tr>'}</tbody></table>
    ${can('staff')||can('exits')?`<form id="fast" class="fg" style="margin-top:12px"><label class="f">Item<input name="n" list="dlAst" placeholder="Uniform set"></label>${dl('dlAst',['Uniform set','Tool kit','Hair dryer','Straightener','Makeup kit','ID card','Locker key','Salon mobile','Tablet'])}<label class="f">Qty<input type="number" name="q" min="1" value="1"></label><label class="f">Value (₹)<input type="number" name="v" min="0" value="0"></label><div style="align-self:end"><button class="btn">Issue item</button></div></form>`:''}`;
  if(cur==='ver'){body=`<h3>Previous employer references (manual verification)</h3><p class="sub">Call each contact, confirm tenure, role and conduct, and record the outcome.</p>${(e.refs||[]).length?(e.refs.map((r,i)=>`<div class="card" style="padding:12px"><div class="row"><b class="sp">${i+1}. ${esc(r.org)}</b>${chip(r.status||'Pending',r.status==='Verified'?'c-ok':r.status==='Discrepancy'?'c-bad':'c-warn')}</div><div class="small muted">${esc(r.role)} · ${esc(r.from)}–${esc(r.to)} · Contact: ${esc(r.contact)} · ${esc(r.phone)}</div>
      <div class="fg" style="margin-top:8px"><label class="f">Outcome<select name="st${i}">${['Pending','Verified','Discrepancy','Unreachable'].map(s=>`<option${r.status===s?' selected':''}>${s}</option>`).join('')}</select></label><label class="f">Call notes<input name="nt${i}" value="${esc(r.note)}"></label></div></div>`).join('')+`<button class="btn" data-act="saveRefs" data-id="${e.id}">Save verification notes</button>`):'<div class="empty">References appear here after the joining form is submitted.</div>'}
    <h3 style="margin-top:18px">Background verification (optional paid service)</h3>${bgvBlock(e)}
    ${e.status==='onboarding'&&e.onb.status==='submitted'&&can('staff')?`<div class="row" style="margin-top:16px"><span class="sp small muted">Activation needs the employer section of the joining form to be complete.</span><button class="btn ok" data-act="activate" data-id="${e.id}">Mark verified & activate</button></div>`:''}`}
  if(cur==='docs'){const ds=S.docs.filter(d=>d.empId===e.id&&d.status!=='hold');body=`${can('docs')||can('staff')?`<div class="row" style="margin-bottom:10px"><select id="genT" style="width:auto">${Object.entries(TPL).filter(([k])=>!['fnf','exit','termination','resign_accept','showcause'].includes(k)).map(([k,t])=>`<option value="${k}">${esc(t.title)}</option>`).join('')}</select><button class="btn p" data-act="genDoc" data-id="${e.id}">Generate</button></div>`:''}${docTable(ds)}`}
  if(cur==='act')body=`<div class="list">${can('staff')?`<div><span class="sp">Issue a written warning</span><button class="btn" data-act="discip" data-id="${e.id}" data-m="warning">Warning letter</button></div><div><span class="sp">Start disciplinary action (show-cause → decision)</span><button class="btn" data-act="discip" data-id="${e.id}" data-m="showcause">Show-cause notice</button></div>`:''}${isBoss()?`<div><span class="sp">Terminate employment with notice / notice pay</span><button class="btn bad" data-act="discip" data-id="${e.id}" data-m="simpliciter">Terminate</button></div>`:''}${e.type==='Probation'&&e.status==='active'&&can('staff')?`<div><span class="sp">Confirm after probation</span><button class="btn ok" data-act="confirmEmp" data-id="${e.id}">Issue confirmation</button></div>`:''}${isBoss()?`<div><span class="sp">Delete this staff record (for wrong entries or staff who never joined). Active staff should leave through Exits so dues and letters are handled.</span><button class="btn bad" data-act="delEmp" data-id="${e.id}">Delete record</button></div>`:''}</div>`;
  if(e.archived){closeModal();return ACT.arch({dataset:{id}})}
  openModal(`<h2>${esc(e.name)}</h2><p class="sub">${e.code} · ${esc(e.designation)} · ${esc(bn(e))} · ${chip(e.status,ESTC[e.status])}</p>${e.status==='exited'?`<div class="note" style="margin:10px 0"><b>Past employee</b> — left on ${fdate(e.lwd)} and removed from all active sections. Full details are kept until <b>${fdate(purgeOn(e))}</b> (${daysLeft(purgeOn(e))} days), then personal details are deleted automatically and statutory records are archived. ${isBoss()?`<button class="btn s bad" data-act="purgeNow" data-id="${e.id}" style="margin-left:6px">Delete details now</button>`:''}</div>`:''}${tb}<div id="empBody">${body}</div>`,()=>{
    const f=$('#fe');if(f&&!ro)f.onsubmit=ev=>{ev.preventDefault();const ph=fval(f,'phone');if(phoneTaken(ph,e.id))return toast('Mobile already used by another employee');readEmp(f,e);audit('Updated profile of '+e.name);render();empModal(id,'ov');toast('Saved')};
    const fer=$('#fer');if(fer)fer.onsubmit=ev=>{ev.preventDefault();F.filter(x=>x.who==='employer').forEach(x=>e.custom[x.id]=fval(fer,'er_'+x.id));audit('Employer section of joining form updated for '+e.name);empModal(id,'onb');toast('Saved')};
    const fee=$('#fee');if(fee)fee.onsubmit=ev=>{ev.preventDefault();const d=(e.onb.data=e.onb.data||{});F.filter(x=>x.who==='employee'&&!['file','refs','qr'].includes(x.type)).forEach(x=>{const v=fval(fee,'ee_'+x.id);if(x.core){if(x.key==='aadhaar'&&v.includes('X'))return;if(x.key==='upi'){e.pay.upi=v;return}d[x.key]=x.key==='aadhaar'&&v?'XXXXXXXX'+v.replace(/\D/g,'').slice(-4):v}else e.custom[x.id]=v});audit('Employer corrected joining details of '+e.name);empModal(id,'onb');toast('Corrections saved')};
    const fp=$('#fpay');if(fp)fp.onsubmit=async ev=>{ev.preventDefault();const d=(e.onb.data=e.onb.data||{});d.bank=fval(fp,'bank');d.acct=fval(fp,'acct');d.ifsc=fval(fp,'ifsc').toUpperCase();const upi=fval(fp,'upi');if(upi&&!UPIRE.test(upi))return toast('UPI ID looks wrong (name@bank)');e.pay.upi=upi;const fl=fp.querySelector('[name=qrf]').files[0];if(fl)e.pay.qr=await shrink(fl);audit('Payment details updated for '+e.name);render();empModal(id,'pay');toast('Saved')};
    const fa=$('#fast');if(fa)fa.onsubmit=ev=>{ev.preventDefault();const n=fval(fa,'n');if(!n)return toast('Item name needed');(e.assets=e.assets||[]).push({id:uid('a'),name:n,qty:+fval(fa,'q')||1,value:+fval(fa,'v')||0,issuedOn:todayS,status:'issued'});audit(`Issued ${n} to ${e.name}`);empModal(id,'ast')};
    document.querySelectorAll('#mbody .tabs button').forEach(b=>b.onclick=()=>{S.ui.tab.emp=b.dataset.v;empModal(id,b.dataset.v)})});
}
const UPIRE=/^[\w.\-]{2,}@[a-zA-Z]{2,}$/;
const shrink=file=>new Promise(res=>{const rd=new FileReader();rd.onload=()=>{const img=new Image();img.onload=()=>{const m=360,k=Math.min(1,m/Math.max(img.width,img.height));const c=document.createElement('canvas');c.width=img.width*k;c.height=img.height*k;c.getContext('2d').drawImage(img,0,0,c.width,c.height);res(c.toDataURL('image/jpeg',.8))};img.onerror=()=>res(null);img.src=rd.result};rd.readAsDataURL(file)});
const astChip=a=>a.status==='approved'?chip('Returned ✓ '+(a.by||''),'c-ok'):a.status==='declared'?chip('Employee says returned','c-warn'):a.status==='lost'?chip('Not returned · recover '+inr(a.value*a.qty),'c-bad'):chip('With employee');
ACT.astSet=el=>{const e=E(el.dataset.id),a=e.assets.find(x=>x.id===el.dataset.a);a.status=el.dataset.v;a.by=actorName();a.at=new Date().toISOString();audit(`${a.name} of ${e.name}: ${el.dataset.v==='approved'?'return approved':'marked not returned'}`);
  const sp=S.seps.find(s=>s.empId===e.id&&!['closed','withdrawn'].includes(s.status));if(sp)tl(sp,`${a.name}: ${el.dataset.v==='approved'?'return approved':'not returned — value to be recovered'}`);render();if($('#modal').hidden===false){sp&&S.ui.sepOpen?sepModal(sp.id):empModal(e.id,'ast')}};
ACT.astDel=el=>{const e=E(el.dataset.id);e.assets=e.assets.filter(a=>a.id!==el.dataset.a);empModal(e.id,'ast')};
CH.lbSet=el=>{const e=E(el.dataset.id);e.lb[el.dataset.k]=+el.value||0;audit(`Leave balance ${el.dataset.k} set to ${el.value} for ${e.name}`);save();toast('Balance updated')};
ACT.delEmp=el=>{const e=E(el.dataset.id);openModal(`<h2>Delete ${esc(e.name)}?</h2><p class="sub">This removes the staff record, attendance, leave and unsigned documents. Finalised payslips stay in payroll history. This cannot be undone.</p><div class="row" style="margin-top:12px"><span class="sp"></span><button class="btn bad" data-act="delEmpGo" data-id="${e.id}">Delete</button></div>`)};
ACT.delEmpGo=el=>{const id=el.dataset.id,n=E(id).name;S.employees=S.employees.filter(e=>e.id!==id);delete S.att[id];delete S.roster[id];S.leaves=S.leaves.filter(l=>l.empId!==id);S.docs=S.docs.filter(d=>d.empId!==id||d.status==='completed');S.seps=S.seps.filter(s=>s.empId!==id);S.tickets=S.tickets.filter(t=>t.empId!==id);S.changeReqs=S.changeReqs.filter(r=>r.empId!==id);audit('Deleted staff record of '+n);closeModal();render();toast('Deleted')};
ACT.saveRefs=el=>{const e=E(el.dataset.id);e.refs.forEach((r,i)=>{r.status=fval($('#mbody'),'st'+i);r.note=fval($('#mbody'),'nt'+i);r.by=actorName();r.at=new Date().toISOString()});audit('Recorded reference checks for '+e.name);empModal(e.id,'ver');toast('Verification saved')};
ACT.activate=el=>{const e=E(el.dataset.id);const miss=S.settings.form.filter(f=>f.who==='employer'&&f.req&&!(e.custom||{})[f.id]);if(miss.length){toast('Complete the employer section first: '+miss.map(f=>f.label).join(', '));return empModal(e.id,'onb')}
  e.status='active';e.onb.status='verified';if(e.pf&&!e.uan)e.uan='Pending generation';audit(e.name+' verified and activated');render();empModal(e.id,'ver');toast(e.name+' is now active')};
ACT.confirmEmp=el=>{const e=E(el.dataset.id);e.type='Permanent';makeDoc('confirmation',e,{});audit('Confirmed '+e.name+' after probation');render();empModal(e.id,'docs');toast('Confirmation letter generated — sign it to send')};
ACT.genDoc=el=>{const e=E(el.dataset.id);const t=$('#genT').value;const d=makeDoc(t,e,{});render();empModal(e.id,'docs');toast(d.title+' generated')};
function bgvBlock(e){const o=S.bgv.find(b=>b.empId===e.id);if(!S.settings.bgv)return`<div class="note i">BGV is an optional add-on. ${isBoss()?'Turn it on under <b>PF/ESI & BGV</b>':'Ask the owner to turn it on'} to order checks. Prices are per check and billed on the monthly HRMS invoice.</div>`;
  if(o)return`<div class="row">${chip(o.status,o.status==='Clear'?'c-ok':'c-warn')}<span class="sp small">${esc(o.pkgName)} · ordered ${fdt(o.at)} · ${inr(o.price)}${o.consent?' · consent signed':' · waiting for employee consent'}</span>${o.status==='In progress'?`<button class="btn s" data-act="bgvDone" data-id="${e.id}">Simulate report</button>`:''}</div>`;
  return`<div class="grid g3">${S.settings.bgvPkgs.map(p=>`<div class="kpi"><b>${inr(p.price)}</b><span class="b">${esc(p.name)}</span><div class="small muted" style="margin:4px 0 8px">${esc(p.desc)}</div><button class="btn s p" data-act="bgvOrder" data-id="${e.id}" data-p="${p.id}">Order</button></div>`).join('')}</div>`}
ACT.bgvOrder=el=>{const e=E(el.dataset.id),p=S.settings.bgvPkgs.find(x=>x.id===el.dataset.p);const has=S.docs.find(d=>d.empId===e.id&&d.type==='bgv'&&d.status==='completed');
  S.bgv.push({id:uid('b'),empId:e.id,pkg:p.id,pkgName:p.name,price:p.price,at:new Date().toISOString(),status:has?'In progress':'Awaiting consent',consent:!!has});if(!has)makeDoc('bgv',e,{});audit('Ordered '+p.name+' BGV for '+e.name);empModal(e.id,'ver');toast(has?'BGV started':'Consent form sent to employee first')};
ACT.bgvDone=el=>{const o=S.bgv.find(b=>b.empId===el.dataset.id);o.status='Clear';o.report='All checks clear (demo)';audit('BGV report received for '+E(el.dataset.id).name);empModal(el.dataset.id,'ver')};

/* ================= OWNER: ATTENDANCE ================= */
VIEWS.attendance=()=>{
  const [tb,cur]=tabs('attendance',[['day','Daily register'],['ot','OT approvals'],['mp','Missed punches'],['month','Monthly muster']]);
  const act=SE().filter(e=>e.status!=='exited');let body='';
  if(cur==='day'){const ds=S.ui.date;body=`<div class="row" style="margin-bottom:10px"><button class="btn s" data-act="dshift" data-n="-1">‹ Prev</button><input type="date" value="${ds}" data-change="setDate" style="width:auto"><button class="btn s" data-act="dshift" data-n="1">Next ›</button><span class="sp"></span><span class="small muted">${DOW[dow(ds)]}${isHol(ds)?' · '+esc(isHol(ds).name):''}</span></div>
    <div class="scroll"><table class="stack"><thead><tr><th>Employee</th><th>Shift</th><th>In</th><th>Meal</th><th>Out</th><th class="n">Worked</th><th>Status</th><th>Overtime</th><th></th></tr></thead><tbody>${act.map(e=>{const o=day(e,ds),r=o.r;
      return`<tr><td><b>${esc(e.name)}</b>${o.flags.length?`<br><span class="small muted">${esc(o.flags.join(' · '))}</span>`:''}</td><td class="small">${o.sh.start}–${o.sh.end}</td><td>${r.in||'—'}${o.late?' '+chip('+'+o.late+'m','c-warn'):''}</td><td class="small">${r.mealOut?r.mealOut+'–'+(r.mealIn||'…'):'—'}</td><td>${r.out||'—'}</td><td class="n">${o.worked?hm(o.worked):'—'}</td><td>${stc(o.status)}</td><td>${otCell(e,o)}</td><td><button class="btn s" data-act="regEdit" data-id="${e.id}" data-d="${ds}">Edit</button></td></tr>`}).join('')}</tbody></table></div>`}
  if(cur==='ot'){const rows=[];act.forEach(e=>[mkShift(curMK,-1),curMK].forEach(mk=>{if(S.payroll[mk])return;dates(mk).forEach(ds=>{const o=day(e,ds);if(o.ot)rows.push({e,o})})}));rows.sort((a,b)=>a.o.ds<b.o.ds?1:-1);
    const pend=rows.filter(x=>x.o.otDecision==='pending');
    body=`<div class="row" style="margin-bottom:10px"><span class="sp small muted">Overtime counts only when you approve it for that day. Approved OT is paid at 2× the ordinary rate.</span>${pend.length?`<button class="btn ok s" data-act="otAll" data-v="approved">Approve all ${pend.length}</button><button class="btn s bad" data-act="otAll" data-v="denied">Deny all</button>`:''}</div>
    ${rows.length?`<table class="stack"><thead><tr><th>Date</th><th>Employee</th><th>Shift</th><th>Punches</th><th class="n">OT claimed</th><th>Decision</th></tr></thead><tbody>${rows.map(({e,o})=>`<tr><td>${fdate(o.ds)}</td><td><b>${esc(e.name)}</b></td><td class="small">${o.sh.start}–${o.sh.end}</td><td class="small">${o.r.in}–${o.r.out}${o.flags.length?'<br>'+esc(o.flags.join(' · ')):''}</td><td class="n">${hm(o.ot)}</td><td>${otCell(e,o)}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">No overtime recorded in open payroll months.</div>'}`}
  if(cur==='mp'){const rows=[];act.forEach(e=>[mkShift(curMK,-1),curMK].forEach(mk=>{if(S.payroll[mk])return;msum(e,mk).mps.forEach(ds=>rows.push({e,ds}))}));
    body=rows.length?`<p class="sub">These days have a punch-in but no punch-out. Enter the correct time with a reason; it is logged in the audit trail.</p><table class="stack"><thead><tr><th>Date</th><th>Employee</th><th>Punch in</th><th></th></tr></thead><tbody>${rows.map(({e,ds})=>`<tr><td>${fdate(ds)}</td><td>${esc(e.name)}</td><td>${rec(e.id,ds).in}</td><td><button class="btn s p" data-act="regEdit" data-id="${e.id}" data-d="${ds}">Regularise</button></td></tr>`).join('')}</tbody></table>`:'<div class="empty">No missed punches.</div>'}
  if(cur==='month'){const mk=S.ui.mk,dl=dates(mk);body=`<div class="row" style="margin-bottom:10px">${monthSel()}<span class="sp"></span><span class="small muted">P present · HD half day · A absent · L leave · WO weekly off · H holiday · MP missed punch</span></div>
    <div class="scroll"><table class="mgrid"><thead><tr><th style="text-align:left">Employee</th>${dl.map(ds=>`<th>${+ds.slice(8)}<br>${DOW[dow(ds)][0]}</th>`).join('')}<th>Paid</th><th>Late</th><th>OT ✓</th></tr></thead><tbody>${act.filter(e=>inMonth(e,mk)).map(e=>{const s=msum(e,mk);return`<tr><td style="text-align:left;white-space:nowrap"><b>${esc(e.name.split(' ')[0])}</b></td>${dl.map(ds=>{const o=day(e,ds);return`<td>${['F','NJ','EX','—'].includes(o.status)?'<span class="muted">·</span>':stc(o.status)}</td>`}).join('')}<td>${s.paid}</td><td>${s.late}</td><td>${hm(s.otApproved)}</td></tr>`}).join('')}</tbody></table></div>`}
  return head('Attendance & overtime','Punches come from the employee app. You approve overtime and fix missed punches; payroll stays locked until both are done.')+tb+`<div class="card">${body}</div>`;
};
function otCell(e,o){if(!o.ot)return'<span class="muted small">—</span>';const d=o.otDecision;
  if(d==='pending')return`<span class="row" style="gap:6px;flex-wrap:nowrap"><span class="small b">${hm(o.ot)}</span><button class="btn s ok" data-act="ot" data-id="${e.id}" data-d="${o.ds}" data-v="approved">Approve</button><button class="btn s bad" data-act="ot" data-id="${e.id}" data-d="${o.ds}" data-v="denied">Deny</button></span>`;
  return`${chip(hm(o.ot)+' '+(d==='approved'?'approved':'denied'),d==='approved'?'c-ok':'c-bad')} ${S.payroll[o.ds.slice(0,7)]?'':`<button class="btn s" data-act="ot" data-id="${e.id}" data-d="${o.ds}" data-v="pending" title="Undo">Undo</button>`}`}
ACT.ot=el=>{const r=rec(el.dataset.id,el.dataset.d);if(el.dataset.v==='pending')delete r.otDecision;else{r.otDecision=el.dataset.v;r.otBy=S.settings.owner;r.otAt=new Date().toISOString()}
  audit(`OT ${el.dataset.v} for ${E(el.dataset.id).name} on ${fdate(el.dataset.d)}`);render()};
ACT.otAll=el=>{let n=0;SE().forEach(e=>[mkShift(curMK,-1),curMK].forEach(mk=>{if(S.payroll[mk])return;dates(mk).forEach(ds=>{const o=day(e,ds);if(o.ot&&o.otDecision==='pending'){o.r.otDecision=el.dataset.v;n++}})}));audit(`Bulk ${el.dataset.v} ${n} OT entries`);render();toast(n+' entries '+el.dataset.v)};
ACT.dshift=el=>{S.ui.date=addDays(S.ui.date,+el.dataset.n);render()};
CH.setDate=el=>{S.ui.date=el.value||todayS;render()};CH.mk=el=>{S.ui.mk=el.value;render()};
CH.rosterShift=el=>{E(el.dataset.id).shiftId=el.value;audit('Shift changed for '+E(el.dataset.id).name);render();toast('Shift updated')};
CH.rosterOff=el=>{E(el.dataset.id).weeklyOff=+el.value;audit('Weekly off changed for '+E(el.dataset.id).name);render();toast('Weekly off updated')};
const monthSel=()=>{const ms=[];for(let k=-4;k<=0;k++)ms.push(mkShift(curMK,k));return`<select data-change="mk" style="width:auto">${ms.map(m=>`<option value="${m}"${m===S.ui.mk?' selected':''}>${mname(m)}${S.payroll[m]?' · finalised':''}</option>`).join('')}</select>`};
ACT.regEdit=el=>{const e=E(el.dataset.id),ds=el.dataset.d,r=rec(e.id,ds)||{};if(S.payroll[ds.slice(0,7)])return toast('That month\'s payroll is finalised. Reopen it first.');
  openModal(`<h2>Edit attendance</h2><p class="sub">${esc(e.name)} · ${fdate(ds)} · shift ${shiftFor(e,ds).start}–${shiftFor(e,ds).end}</p><form id="fr"><div class="fg"><label class="f">Punch in<input type="time" name="in" value="${r.in||''}"></label><label class="f">Meal start<input type="time" name="mo" value="${r.mealOut||''}"></label><label class="f">Meal end<input type="time" name="mi" value="${r.mealIn||''}"></label><label class="f">Punch out<input type="time" name="out" value="${r.out||''}"></label></div>
  <label class="f" style="margin-top:12px">Reason (required, visible to employee)<input name="why" required placeholder="Forgot to punch out; confirmed with CCTV"></label><div class="row" style="margin-top:14px"><button type="button" class="btn bad" data-act="regClear" data-id="${e.id}" data-d="${ds}">Mark absent (clear punches)</button><span class="sp"></span><button class="btn p">Save</button></div></form>`,()=>{
  $('#fr').onsubmit=ev=>{ev.preventDefault();const f=$('#fr');const why=fval(f,'why');if(!why)return toast('Add a reason');
    const n={in:fval(f,'in')||null,mealOut:fval(f,'mo')||null,mealIn:fval(f,'mi')||null,out:fval(f,'out')||null,reg:{by:S.settings.owner,why,at:new Date().toISOString()},src:'Regularised by owner'};
    if(!n.in)return toast('Punch in time needed');setRec(e.id,ds,n);audit(`Regularised ${e.name} on ${fdate(ds)}: ${why}`);closeModal();render();toast('Attendance updated')}})};
ACT.regClear=el=>{delete (S.att[el.dataset.id]||{})[el.dataset.d];audit('Cleared punches for '+E(el.dataset.id).name+' on '+fdate(el.dataset.d));closeModal();render()};
document.addEventListener('submit',ev=>{if(ev.target.id==='fs'){ev.preventDefault();const f=ev.target;const n=fval(f,'n')||'Shift '+(S.shifts.length+1);S.shifts.push({id:uid('s'),name:n,start:fval(f,'s'),end:fval(f,'e')});audit('Added shift '+n);render()}});

/* ================= OWNER: LEAVE ================= */
VIEWS.leave=()=>{const ins=l=>{const e=E(l.empId);return!!e&&e.status!=='exited'&&inScope(e)};const pend=S.leaves.filter(l=>l.status==='pending'&&ins(l)),hist=S.leaves.filter(l=>l.status!=='pending'&&ins(l)).sort((a,b)=>a.from<b.from?1:-1).slice(0,30);
  const lrow=(l,act)=>{const e=E(l.empId);return`<tr><td><b>${esc(e.name)}</b><br><span class="small muted">${esc(bn(e))}</span></td><td>${chip(lname(l.type),lpaid(l.type)?'c-info':'c-bad')}${l.half?' '+chip('Half day'):''}</td><td>${fdate(l.from)}${l.to!==l.from?' – '+fdate(l.to):''}</td><td class="small">${esc(l.reason)}${act&&lpaid(l.type)?`<br><span class="muted">Balance ${e.lb[l.type]??0} · needs ${lvDays(l)}</span>`:''}</td><td>${act?`<span class="row" style="gap:6px;flex-wrap:nowrap"><button class="btn s ok" data-act="lv" data-id="${l.id}" data-v="approved">Approve</button><button class="btn s bad" data-act="lv" data-id="${l.id}" data-v="rejected">Reject</button></span>`:chip(l.status,l.status==='approved'?'c-ok':'c-bad')}</td></tr>`};
  return head('Leave','Approve requests; balances update automatically. Leave types and quotas are set by the owner in Customise.',isBoss()?`<button class="btn" data-act="go" data-v="customise" data-t="leave">Edit leave types</button>`:'')+
  `<div class="card"><h2>Requests (${pend.length})</h2>${pend.length?`<table class="stack"><thead><tr><th>Employee</th><th>Type</th><th>Dates</th><th>Reason</th><th></th></tr></thead><tbody>${pend.map(l=>lrow(l,1)).join('')}</tbody></table>`:'<div class="empty">No pending requests.</div>'}</div>
  <div class="card"><h2>Balances</h2><p class="sub" style="margin-bottom:8px">Edit any number directly.</p><div class="scroll"><table class="stack"><thead><tr><th>Employee</th>${LT().map(t=>`<th class="n">${esc(t.name)}</th>`).join('')}</tr></thead><tbody>${SE().filter(e=>e.status!=='exited').map(e=>`<tr><td>${esc(e.name)}</td>${LT().map(t=>`<td class="n"><input type="number" step="0.5" min="0" value="${e.lb[t.code]??0}" data-change="lbSet" data-id="${e.id}" data-k="${t.code}" style="width:80px;padding:5px;min-height:32px;text-align:right"></td>`).join('')}</tr>`).join('')}</tbody></table></div></div>
  <div class="card"><h2>History</h2><table class="stack"><thead><tr><th>Employee</th><th>Type</th><th>Dates</th><th>Reason</th><th>Status</th></tr></thead><tbody>${hist.map(l=>lrow(l,0)).join('')}</tbody></table></div>`};
const lvDays=l=>l.half?0.5:Math.round((new Date(l.to)-new Date(l.from))/864e5)+1;
ACT.lv=el=>{const l=S.leaves.find(x=>x.id===el.dataset.id),e=E(l.empId);l.status=el.dataset.v;l.decidedOn=todayS;l.by=actorName();
  if(l.status==='approved'&&lpaid(l.type)){const n=lvDays(l);if((e.lb[l.type]??0)<n){l.type='LOP';toast('Balance insufficient — approved as leave without pay')}else e.lb[l.type]-=n}
  audit(`Leave ${l.status} for ${e.name} (${fdate(l.from)})`);render()};

/* ================= OWNER: PAYROLL ================= */
VIEWS.payroll=()=>{const mk=S.ui.mk,pr=S.payroll[mk];let body='';
  if(pr&&pr.status==='finalized'){const rows=pr.rows;const tot=k=>rows.reduce((a,r)=>a+r[k],0);
    body=`<div class="note i" style="margin-bottom:14px">Finalised by ${esc(pr.by)} on ${fdt(pr.at)}. Payslips are visible to employees. To change anything, reopen with a reason.</div>
    <div class="grid g4" style="margin-bottom:14px"><div class="kpi"><b>${inr(tot('gross'))}</b><span>Gross earnings</span></div><div class="kpi"><b>${inr(tot('net'))}</b><span>Net to bank</span></div><div class="kpi"><b>${inr(tot('pfEE')+tot('pfER')+tot('adm')+tot('edli'))}</b><span>PF remittance</span></div><div class="kpi"><b>${inr(tot('esiEE')+tot('esiER'))}</b><span>ESI remittance</span></div></div>
    ${register(rows,false)}<div class="row" style="margin-top:14px"><button class="btn" data-act="bankFile">Bank transfer file</button>${S.settings.pf?'<button class="btn" data-act="ecr">EPF ECR file</button>':''}${S.settings.esi?'<button class="btn" data-act="esicFile">ESIC contribution file</button>':''}<span class="sp"></span><button class="btn bad" data-act="reopen">Reopen payroll</button></div>`}
  else{const c=payChecks(mk);const rows=c.emps.map(e=>payCalc(e,mk));const proj=mk===curMK;
    const ck=(ok,t,n,go,tab)=>`<div class="check"><span class="ic" style="background:${ok?'var(--okb)':'var(--badb)'};color:${ok?'var(--ok)':'var(--bad)'}">${ok?'✓':n}</span><div class="sp"><b>${t}</b>${ok?'':`<div class="small muted">${n} item(s) pending</div>`}</div>${ok?'':`<button class="btn s" data-act="go" data-v="${go}" data-t="${tab||''}">Resolve</button>`}</div>`;
    body=`<div class="grid g2"><div class="card" style="margin:0"><h2>Before you can generate payroll</h2>
      ${ck(!c.ot.length,'Every overtime entry approved or denied',c.ot.length,'attendance','ot')}${ck(!c.mp.length,'Missed punches regularised',c.mp.length,'attendance','mp')}${ck(!c.lv.length,'Leave requests decided',c.lv.length,'leave')}${ck(!c.perf.length,'Target achievement entered and marked final',c.perf.length,'performance')}
      ${proj?`<div class="note" style="margin-top:10px">${mname(mk)} is still running: ${daysIn(mk)-NOW.getDate()} future day(s) are counted as scheduled. Best to finalise after the month ends.</div>`:''}
      <label class="chk" style="margin-top:12px"><input type="checkbox" id="confirmPay"> I have reviewed attendance, OT, leave, incentives and deductions for ${mname(mk)}.</label>
      <button class="btn p" style="margin-top:12px;width:100%" data-act="finalize" ${c.ok?'':'disabled'}>Generate payroll & release payslips</button></div>
      <div class="card" style="margin:0"><h2>Draft totals</h2><div class="list"><div><span class="sp">Employees</span><b>${rows.length}</b></div><div><span class="sp">Gross earnings</span><b>${inr(rows.reduce((a,r)=>a+r.gross,0))}</b></div><div><span class="sp">Approved OT pay</span><b>${inr(rows.reduce((a,r)=>a+r.otPay,0))}</b></div><div><span class="sp">Incentives</span><b>${inr(rows.reduce((a,r)=>a+r.inc+r.pinc,0))}</b></div><div><span class="sp">Net payable</span><b>${inr(rows.reduce((a,r)=>a+r.net,0))}</b></div><div><span class="sp">Employer cost (incl. PF/ESI)</span><b>${inr(rows.reduce((a,r)=>a+r.cost,0))}</b></div></div></div></div>
      <h2 style="margin:18px 0 8px">Draft register</h2><p class="sub" style="margin-bottom:8px">Edit advances, other deductions and TDS here. Everything else comes from attendance, OT decisions and targets.</p>${register(rows,true)}`}
  return head('Payroll',`Salary for a month is generated only after you finish all approvals for that month.`,monthSel())+`<div class="card">${body}</div>`};
function register(rows,edit){const mk=S.ui.mk;return`<div class="scroll"><table class="stack"><thead><tr><th>Employee</th><th class="n">Paid days</th><th class="n">Fixed earned</th><th class="n">OT pay</th><th class="n">Incentive</th><th class="n">Gross</th><th class="n">PF</th><th class="n">ESI</th><th class="n">PT</th><th class="n">Advance / other / TDS</th><th class="n">Net pay</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td><b>${esc(r.name)}</b>${r.warn.length?'<br>'+chip(r.warn[0],'c-bad'):''}</td><td class="n">${r.paidDays}/${r.days}${r.latePen?`<br><span class="small muted">−${r.latePen} late</span>`:''}</td><td class="n">${inr(r.basic+r.hra+r.spl)}</td><td class="n">${inr(r.otPay)}<br><span class="small muted">${hm(r.otMin)}</span></td><td class="n">${inr(r.inc+r.pinc)}</td><td class="n b">${inr(r.gross)}</td><td class="n">${inr(r.pfEE)}</td><td class="n">${inr(r.esiEE)}</td><td class="n">${inr(r.pt)}</td>
  <td class="n">${edit?`<span class="row" style="gap:4px;flex-wrap:nowrap;justify-content:flex-end">${['adv','oth','tds'].map(k=>`<input aria-label="${k}" type="number" min="0" value="${r[k]||''}" placeholder="${k==='adv'?'Adv':k==='oth'?'Other':'TDS'}" data-change="adj" data-id="${r.empId}" data-k="${k}" style="width:76px;padding:5px;min-height:32px;font-size:14px">`).join('')}</span>`:inr(r.adv+r.oth+r.tds)}</td><td class="n b">${inr(r.net)}</td><td><span class="row" style="gap:4px;flex-wrap:nowrap"><button class="btn s" data-act="slip" data-id="${r.empId}" data-m="${mk}">Payslip</button>${edit?'':(((S.pays[mk]||{})[r.empId])?chip('Paid '+S.pays[mk][r.empId].mode,'c-ok'):`<button class="btn s p" data-act="payOne" data-id="${r.empId}">Pay</button>`)}</span></td></tr>`).join('')}</tbody></table></div>`}
CH.adj=el=>{const mk=S.ui.mk;((S.adj[mk]=S.adj[mk]||{})[el.dataset.id]=S.adj[mk][el.dataset.id]||{})[el.dataset.k]=+el.value||0;render()};
ACT.finalize=()=>{if(!$('#confirmPay').checked)return toast('Tick the review confirmation first');const mk=S.ui.mk;if(!payChecks(mk).ok)return;finalize(mk,S.settings.owner+' (Owner)');render();toast('Payroll generated — payslips released to employees')};
ACT.reopen=()=>openModal(`<h2>Reopen ${mname(S.ui.mk)} payroll?</h2><p class="sub">Payslips will be withdrawn from employees until you finalise again. The reason is logged.</p><input id="why" placeholder="Reason, e.g. missed incentive for Priya"><div class="row" style="margin-top:14px"><span class="sp"></span><button class="btn bad" data-act="reopenGo">Reopen</button></div>`);
ACT.reopenGo=()=>{const w=$('#why').value.trim();if(!w)return toast('Reason required');delete S.payroll[S.ui.mk];audit('Reopened payroll '+mname(S.ui.mk)+': '+w);closeModal();render()};
function slipHTML(r,mk){const e=E(r.empId),s=S.settings;const L=[['Basic wages',r.basic],['House rent allowance',r.hra],['Special allowance',r.spl],['Overtime ('+hm(r.otMin)+' @ 2×)',r.otPay],['Service incentive ('+Math.round(r.ach*100)+'% of target)',r.inc],['Product incentive',r.pinc]];
  const D=[['Provident fund (12%)',r.pfEE],['ESI (0.75%)',r.esiEE],['Professional tax',r.pt],['Salary advance',r.adv],['Other deductions',r.oth],['Income tax (TDS)',r.tds]];
  return`<div class="doc">${LH()}<h2>PAYSLIP — ${mname(mk).toUpperCase()}</h2><table><tr><td>Name</td><td>${esc(e.name)}</td><td>Employee code</td><td>${e.code}</td></tr><tr><td>Designation</td><td>${esc(e.designation)}</td><td>Date of joining</td><td>${fdate(e.doj)}</td></tr><tr><td>UAN</td><td>${esc(s.pf&&e.pf?e.uan:'Not applicable')}</td><td>ESIC IP no.</td><td>${esc(s.esi&&e.esi?e.esic:'Not applicable')}</td></tr><tr><td>Bank a/c</td><td>${esc(mask((e.onb.data||{}).acct))}</td><td>Days paid</td><td>${r.paidDays} of ${r.days} (LOP ${r.lop})</td></tr></table><br>
  <table><tr><th>Earnings</th><th>₹</th><th>Deductions</th><th>₹</th></tr>${L.map((l,i)=>`<tr><td>${esc(l[0])}</td><td style="text-align:right">${Math.round(l[1]).toLocaleString('en-IN')}</td><td>${esc(D[i][0])}</td><td style="text-align:right">${Math.round(D[i][1]).toLocaleString('en-IN')}</td></tr>`).join('')}
  <tr><td><b>Gross earnings</b></td><td style="text-align:right"><b>${r.gross.toLocaleString('en-IN')}</b></td><td><b>Total deductions</b></td><td style="text-align:right"><b>${r.ded.toLocaleString('en-IN')}</b></td></tr><tr><td colspan="3"><b>Net pay credited</b></td><td style="text-align:right"><b>${inr(r.net)}</b></td></tr></table>
  <p style="font-size:12px">Employer contributions (not deducted from you): PF ${inr(r.pfER)}, PF admin & EDLI ${inr(r.adm+r.edli)}, ESI ${inr(r.esiER)}. Target ${inr(r.target)} · achieved ${inr(r.svc)} · retail ${inr(r.prod)}. Late marks ${r.lates}${r.latePen?' ('+r.latePen+' day LOP)':''}.</p><p style="font-size:11px;color:#777">Computer-generated payslip; no signature required. Wages paid under the Code on Wages, 2019.</p></div>`}
ACT.slip=el=>{const mk=el.dataset.m,pr=S.payroll[mk];const r=pr?pr.rows.find(x=>x.empId===el.dataset.id):payCalc(E(el.dataset.id),mk);openModal(`<h2>Payslip${pr?'':' (draft)'}</h2>${slipHTML(r,mk)}<p class="small muted" style="margin-top:8px">The live version emails and downloads payslips as PDF.</p>`)};
const copyBox=(t,txt)=>openModal(`<h2>${esc(t)}</h2><pre id="cp">${esc(txt)}</pre><div class="row" style="margin-top:12px"><span class="sp small muted">Copy and upload to your bank / EPFO / ESIC portal. Live version downloads the file.</span><button class="btn p" data-act="copy">Copy</button></div>`);
ACT.copy=()=>{navigator.clipboard.writeText($('#cp').textContent).then(()=>toast('Copied'),()=>toast('Select the text and copy'))};
ACT.bankFile=()=>{const pr=S.payroll[S.ui.mk];copyBox('Bank transfer file — '+mname(S.ui.mk),'Beneficiary Name,Account No,IFSC,UPI ID,Amount,Narration\n'+pr.rows.map(r=>{const e=E(r.empId)||{onb:{},pay:{}};const d=(e.onb||{}).data||{};return`${r.name},${d.acct||''},${d.ifsc||''},${(e.pay||{}).upi||''},${r.net},Salary ${mshort(S.ui.mk)}`}).join('\n'))};
ACT.payOne=el=>{const mk=S.ui.mk,r=S.payroll[mk].rows.find(x=>x.empId===el.dataset.id),e=E(r.empId)||{onb:{},pay:{}};const d=(e.onb||{}).data||{},p=e.pay||{};
  openModal(`<h2>Pay ${esc(r.name)} — ${inr(r.net)}</h2><p class="sub">Salary for ${mname(mk)}. Pay through your bank app, then record the reference here.</p><div class="grid g2"><div class="card" style="margin:0"><h3>Bank transfer</h3><div class="list small"><div><span class="sp muted">Bank</span><b>${esc(d.bank||'—')}</b></div><div><span class="sp muted">Account</span><b>${esc(d.acct||'—')}</b></div><div><span class="sp muted">IFSC</span><b>${esc(d.ifsc||'—')}</b></div></div></div><div class="card" style="margin:0"><h3>UPI</h3><p class="b">${esc(p.upi||'No UPI ID')}</p>${p.qr?`<img src="${p.qr}" alt="UPI QR" style="width:160px;border-radius:10px">`:'<p class="small muted">No QR uploaded.</p>'}</div></div><div class="fg" style="margin-top:12px"><label class="f">Paid by<select id="pm"><option>Bank transfer</option><option>UPI</option><option>Cash (with receipt)</option></select></label><label class="f">UTR / reference<input id="pr"></label></div><div class="row" style="margin-top:12px"><span class="sp"></span><button class="btn ok" data-act="payRec" data-id="${r.empId}">Record payment</button></div>`)};
ACT.payRec=el=>{const mk=S.ui.mk;const ref=$('#pr').value.trim();if(!ref)return toast('Enter the UTR / reference');(S.pays[mk]=S.pays[mk]||{})[el.dataset.id]={mode:$('#pm').value,ref,at:new Date().toISOString(),by:actorName()};audit(`Salary ${mname(mk)} paid to ${E(el.dataset.id)?.name||''} via ${$('#pm').value} (${ref})`);closeModal();render();toast('Payment recorded')};
ACT.ecr=()=>{const pr=S.payroll[S.ui.mk];copyBox('EPF ECR — '+mname(S.ui.mk),pr.rows.filter(r=>r.pfEE).map(r=>{const w=Math.min(r.wages,S.settings.pfCeil);return[E(r.empId).uan,r.name.toUpperCase(),r.gross,w,w,w,r.pfEE,r.eps,r.pfER-r.eps,Math.round(r.lop),0].join('#~#')}).join('\n'))};
ACT.esicFile=()=>{const pr=S.payroll[S.ui.mk];copyBox('ESIC monthly contribution — '+mname(S.ui.mk),'IP Number,IP Name,No of Days,Total Monthly Wages,Reason Code\n'+pr.rows.filter(r=>r.esiEE).map(r=>`${E(r.empId).esic},${r.name},${Math.floor(r.paidDays)},${r.gross},`).join('\n'))};

/* ================= OWNER: PRODUCTIVITY ================= */
VIEWS.performance=()=>{const mk=S.ui.mk,open=!S.payroll[mk],emps=SE().filter(e=>inMonth(e,mk));
  const months=[];for(let k=-4;k<=0;k++)months.push(mkShift(curMK,k));
  const sel=(S.ui.tab.perfEmp&&SE().some(e=>e.id===S.ui.tab.perfEmp&&e.status!=='exited'))?S.ui.tab.perfEmp:SE().find(e=>e.target&&e.status!=='exited')?.id;const se=E(sel);
  const series=se?months.map(m=>{const p=(S.perf[se.id]||{})[m]||{};const pr=S.payroll[m];const r=pr?pr.rows.find(x=>x.empId===se.id):null;return{m,t:p.target||0,a:p.service||0,prod:p.product||0,cost:r?r.cost:(inMonth(se,m)?payCalc(se,m).cost:0),fin:!!pr}}):[];
  return head('Productivity','Monthly target vs achievement against what each person costs. Feeds incentives in payroll.',monthSel())+
  `<div class="card"><h2>${mname(mk)} — targets & achievement</h2><p class="sub" style="margin-bottom:10px">${open?'Enter sales from your billing software (or the live POS integration) and tick Final once the month is closed. Payroll needs every row final.':'Payroll finalised — figures locked.'}</p>
  <div class="scroll"><table class="stack"><thead><tr><th>Employee</th><th class="n">Target</th><th class="n">Service sales</th><th class="n">Retail sales</th><th>Achievement</th><th class="n">Salary cost</th><th class="n">Revenue ÷ cost</th><th>Final</th></tr></thead><tbody>${emps.map(e=>{const p=(S.perf[e.id]=S.perf[e.id]||{})[mk]||{target:e.target,service:0,product:0};const pr=S.payroll[mk];const r=pr?pr.rows.find(x=>x.empId===e.id):payCalc(e,mk);const a=p.target?p.service/p.target:0;
    const inp=(k)=>open?`<input type="number" min="0" value="${p[k]||0}" data-change="perf" data-id="${e.id}" data-k="${k}" style="width:110px;padding:5px;min-height:34px">`:inr(p[k]);
    return`<tr><td><b>${esc(e.name)}</b><br><span class="small muted">${esc(e.designation)}</span></td><td class="n">${inp('target')}</td><td class="n">${inp('service')}</td><td class="n">${inp('product')}</td><td style="min-width:140px">${p.target?`<div class="bars"><div class="t" style="height:10px"><i style="width:${Math.min(100,a*100)}%;background:${a>=1?'var(--ok)':a>=.8?'var(--brass)':'var(--bad)'}"></i></div></div><span class="small">${Math.round(a*100)}%</span>`:'<span class="small muted">No target</span>'}</td><td class="n">${inr(r.cost)}</td><td class="n b">${r.cost?((p.service+p.product)/r.cost).toFixed(1)+'×':'—'}</td><td>${open?`<input type="checkbox" ${p.final?'checked':''} data-change="perfFinal" data-id="${e.id}" style="width:22px;min-height:22px">`:'✓'}</td></tr>`}).join('')}</tbody></table></div></div>
  <div class="card"><div class="row"><h2 class="sp">Month on month</h2><select data-change="perfEmp" style="width:auto">${SE().filter(e=>e.target&&e.status!=='exited').map(e=>`<option value="${e.id}"${e.id===sel?' selected':''}>${esc(e.name)}</option>`).join('')}</select></div>
  ${se?`<div class="fig" id="mom" data-s='${esc(JSON.stringify(series))}'><svg></svg></div><div class="row small muted" style="gap:16px;margin-top:6px"><span><span class="dot" style="display:inline-block;background:var(--line);border:1px solid var(--mute)"></span> Target</span><span><span class="dot" style="display:inline-block;background:var(--berry)"></span> Service sales</span><span><span class="dot" style="display:inline-block;background:var(--brass)"></span> Salary cost</span></div>
  <table class="stack" style="margin-top:10px"><thead><tr><th>Month</th><th class="n">Target</th><th class="n">Achieved</th><th class="n">%</th><th class="n">Salary cost</th><th class="n">Revenue ÷ cost</th></tr></thead><tbody>${series.filter(x=>x.t||x.a).map(x=>`<tr><td>${mname(x.m)}${x.fin?'':' (open)'}</td><td class="n">${inr(x.t)}</td><td class="n">${inr(x.a)}</td><td class="n">${x.t?Math.round(x.a/x.t*100):0}%</td><td class="n">${inr(x.cost)}</td><td class="n b">${x.cost?((x.a+x.prod)/x.cost).toFixed(1)+'×':'—'}</td></tr>`).join('')}</tbody></table>`:''}</div>`};
CH.perf=el=>{const mk=S.ui.mk,e=E(el.dataset.id);const p=(S.perf[e.id]=S.perf[e.id]||{})[mk]=S.perf[e.id][mk]||{target:e.target,service:0,product:0};p[el.dataset.k]=+el.value||0;render()};
CH.perfFinal=el=>{const mk=S.ui.mk,e=E(el.dataset.id);const p=(S.perf[e.id]=S.perf[e.id]||{})[mk]=S.perf[e.id][mk]||{target:e.target,service:0,product:0};p.final=el.checked;render()};
CH.perfEmp=el=>{S.ui.tab.perfEmp=el.value;render()};
function drawMom(){const f=$('#mom');if(!f)return;const svg=f.querySelector('svg');const data=JSON.parse(f.dataset.s);
  const draw=()=>{const W=f.clientWidth,H=f.clientHeight;if(W<120||H<80)return;const pl=W<520?8:56,pb=26,pt=10,n=data.length;const mx=Math.max(1,...data.map(d=>Math.max(d.t,d.a,d.cost)))*1.1;const bw=(W-pl-10)/n;const y=v=>pt+(H-pt-pb)*(1-v/mx);
    let h='';if(W>=520)for(let i=0;i<=4;i++){const v=mx*i/4;h+=`<line x1="${pl}" x2="${W}" y1="${y(v)}" y2="${y(v)}" stroke="var(--line)"/><text x="${pl-6}" y="${y(v)+4}" text-anchor="end" font-size="11" fill="var(--mute)">${Math.round(v/1000)}k</text>`}
    data.forEach((d,i)=>{const x=pl+i*bw+bw*.18,w=bw*.64;h+=`<rect x="${x}" y="${y(d.t)}" width="${w}" height="${H-pb-y(d.t)}" fill="var(--line)" rx="4"/><rect x="${x+w*.18}" y="${y(d.a)}" width="${w*.64}" height="${H-pb-y(d.a)}" fill="var(--berry)" rx="3"/><text x="${x+w/2}" y="${H-8}" text-anchor="middle" font-size="12" fill="var(--mute)">${mshort(d.m)}</text>`});
    h+=`<polyline fill="none" stroke="var(--brass)" stroke-width="2.5" points="${data.map((d,i)=>(pl+i*bw+bw/2)+','+y(d.cost)).join(' ')}"/>`+data.map((d,i)=>`<circle cx="${pl+i*bw+bw/2}" cy="${y(d.cost)}" r="4" fill="var(--brass)"/>`).join('');svg.innerHTML=h};
  draw();if(drawMom.ro)drawMom.ro.disconnect();drawMom.ro=new ResizeObserver(draw);drawMom.ro.observe(f)}

/* ================= DOCUMENTS ================= */
function docTable(ds,emp){return ds.length?`<table class="stack"><thead><tr><th>Document</th>${emp?'':'<th>Employee</th>'}<th>Created</th><th>Status</th><th></th></tr></thead><tbody>${ds.map(d=>{const[s,c]=docStatus(d);return`<tr><td><b>${esc(d.title)}</b><br><span class="small muted">${d.fp}</span></td>${emp?'':`<td>${esc(E(d.empId).name)}</td>`}<td class="small">${fdt(d.created)}</td><td>${chip(s,c)}</td><td><button class="btn s ${d.status!=='completed'&&nextSigner(d)===(isOwner()?'employer':'employee')?'p':''}" data-act="doc" data-id="${d.id}">${d.status!=='completed'&&nextSigner(d)===(isOwner()?'employer':'employee')?'Review & sign':'View'}</button></td></tr>`}).join('')}</tbody></table>`:'<div class="empty">No documents yet.</div>'}
VIEWS.documents=()=>{const [tb,cur]=tabs('documents',[['me','Waiting for you'],['emp','Waiting for employee'],['all','All documents'],['tpl','Templates']]);
  let ds=S.docs.filter(d=>!['void','hold'].includes(d.status)&&E(d.empId)&&E(d.empId).status!=='exited'&&inScope(E(d.empId)));if(cur==='me')ds=ds.filter(d=>d.status!=='completed'&&nextSigner(d)==='employer');if(cur==='emp')ds=ds.filter(d=>d.status!=='completed'&&nextSigner(d)==='employee');
  const body=cur==='tpl'?`<p class="sub">Standard templates for all salons, drafted for the Labour Codes in force since 21 November 2025. Placeholders fill from the employee record.</p><table class="stack"><thead><tr><th>Template</th><th>Signed by</th><th>Used in</th></tr></thead><tbody>${Object.entries(TPL).map(([k,t])=>`<tr><td><b>${esc(t.title)}</b></td><td>${t.signers.map(s=>s==='employer'?'Employer':'Employee').join(' → ')}</td><td class="small muted">${{joining:'Onboarding',appointment:'Onboarding',nda:'Onboarding',handbook:'Onboarding',bgv:'BGV',confirmation:'Probation',warning:'Discipline',showcause:'Discipline',termination:'Exit',resign_accept:'Exit',relieving:'Exit',experience:'Exit',fnf:'Exit',exit:'Exit'}[k]}</td></tr>`).join('')}</tbody></table>`:docTable(ds);
  return head('Documents & e-sign','Every letter is generated from the record, signed by both sides with OTP, fingerprinted and kept with an audit trail.')+tb+`<div class="card">${body}</div>`};
ACT.doc=el=>docModal(el.dataset.id);
function docModal(id){const d=S.docs.find(x=>x.id===id),e=E(d.empId),me=isOwner()?'employer':'employee';const n=nextSigner(d);const canSign=d.status!=='completed'&&n===me&&(isOwner()?(isBoss()||(user()&&user().perms.docs)):S.ui.role===d.empId);
  openModal(`<h2>${esc(d.title)}</h2><p class="sub">${esc(e.name)} · ${chip(...docStatus(d))}</p>${docHTML(d)}
  <details style="margin-top:10px"><summary class="small">Audit trail</summary><div class="list small">${d.audit.map(a=>`<div><span class="muted" style="width:150px">${fdt(a.at)}</span><span class="sp">${esc(a.text)}</span></div>`).join('')}</div></details>
  ${canSign?signUI(me==='employer'?(user()?user().name:S.settings.owner):e.name,me==='employee'?e.phone:(user()?user().phone:S.settings.phone)):`<p class="small muted" style="margin-top:10px">${d.status==='completed'?'Fully signed. The live version downloads this as a signed PDF.':n?'Waiting for '+(n==='employer'?'the employer'+(isOwner()&&!isBoss()&&!(user()&&user().perms.docs)?' (owner, or a manager with signing permission)':''):'the employee')+' to sign.':''}</p>`}
  ${isOwner()&&can('staff')&&d.status!=='completed'?`<div class="row" style="margin-top:8px"><span class="sp"></span><button class="btn s bad" data-act="voidDoc" data-id="${d.id}">Withdraw document</button></div>`:''}`,()=>{if(canSign)mountSign(name=>signDoc(d,me,name))})}
function signUI(name,phone){return`<div class="card" style="margin-top:14px;background:var(--blush)"><h3>Sign electronically</h3><div class="tabs" style="margin-top:8px"><button type="button" class="on" data-m="type">Type</button><button type="button" data-m="draw">Draw</button></div>
  <div id="sgType"><label class="f">Full name as signature<input id="sgName" value="${esc(name)}"></label></div><div id="sgDraw" hidden><canvas class="pad" id="pad"></canvas><button type="button" class="btn s" id="padClr" style="margin-top:6px">Clear</button></div>
  <div class="fg" style="margin-top:10px"><label class="f">OTP sent to ${esc(phone)} (demo OTP 123456)<input id="sgOtp" inputmode="numeric" maxlength="6" placeholder="6-digit OTP"></label></div>
  <label class="chk" style="margin-top:10px"><input type="checkbox" id="sgOk"> I have read this document and agree to sign it electronically under the Information Technology Act, 2000.</label>
  <button class="btn p" id="sgGo" style="margin-top:12px;width:100%">Sign document</button></div>`}
function mountSign(done){let mode='type',drawn=false;const c=$('#pad'),ctx=c.getContext('2d');
  const fit=()=>{c.width=c.clientWidth*2;c.height=c.clientHeight*2;ctx.scale(2,2);ctx.lineWidth=2.2;ctx.lineCap='round';ctx.strokeStyle='#173a8a'};
  document.querySelectorAll('#mbody .card .tabs button').forEach(b=>b.onclick=()=>{mode=b.dataset.m;document.querySelectorAll('#mbody .card .tabs button').forEach(x=>x.classList.toggle('on',x===b));$('#sgType').hidden=mode!=='type';$('#sgDraw').hidden=mode!=='draw';if(mode==='draw')fit()});
  let down=false;const pos=ev=>{const r=c.getBoundingClientRect();return[ev.clientX-r.left,ev.clientY-r.top]};
  c.onpointerdown=ev=>{down=true;drawn=true;ctx.beginPath();ctx.moveTo(...pos(ev));c.setPointerCapture(ev.pointerId)};c.onpointermove=ev=>{if(!down)return;ctx.lineTo(...pos(ev));ctx.stroke()};c.onpointerup=()=>down=false;
  $('#padClr').onclick=()=>{ctx.clearRect(0,0,c.width,c.height);drawn=false};
  $('#sgGo').onclick=()=>{if($('#sgOtp').value!=='123456')return toast('Enter the OTP (demo: 123456)');if(!$('#sgOk').checked)return toast('Tick the consent box');
    const nm=$('#sgName').value.trim();if(!nm)return toast('Type your name');if(mode==='draw'&&!drawn)return toast('Draw your signature');
    done({name:nm,img:mode==='draw'?c.toDataURL('image/png'):null,method:(mode==='draw'?'Drawn':'Typed')+' + OTP'})}}
function signDoc(d,who,s){d.signs[who]={name:s.name,img:s.img,method:s.method,at:new Date().toISOString(),device:navigator.userAgent.slice(0,60)};d.audit.push({at:new Date().toISOString(),text:`Signed by ${who} (${s.name}) · ${s.method} · fingerprint ${d.fp}`});
  const n=nextSigner(d);if(!n){d.status='completed';d.audit.push({at:new Date().toISOString(),text:'All parties signed — document completed'});onDocComplete(d)}else{d.status='awaiting_'+n;d.audit.push({at:new Date().toISOString(),text:'Sent to '+n+' for signature'})}
  audit(`${d.title} signed by ${who==='employer'?'employer':s.name}`);closeModal();render();toast(n?'Signed and sent to '+(n==='employer'?'employer':'employee'):'Document completed')}
function onDocComplete(d){const e=E(d.empId);if(d.type==='handbook')S.acks[e.id]=todayS;if(d.type==='bgv'){const o=S.bgv.find(b=>b.empId===e.id&&!b.consent);if(o){o.consent=true;o.status='In progress'}}}
ACT.voidDoc=el=>{const d=S.docs.find(x=>x.id===el.dataset.id);d.status='void';d.audit.push({at:new Date().toISOString(),text:'Withdrawn by employer'});audit('Withdrew '+d.title);closeModal();render()};
